import{_ as t,o as e,c as n,a3 as s}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Autonomous-driving system map","description":"A layer-by-layer diagnostic map from sensors and chassis interfaces through perception, planning, control, and validation.","frontmatter":{"title":"Autonomous-driving system map","description":"A layer-by-layer diagnostic map from sensors and chassis interfaces through perception, planning, control, and validation.","content_type":"guide","status":"design guidance","keywords":["system architecture","time synchronization","coordinate frames","planning","control"]},"headers":[],"relativePath":"en/about/system-map.md","filePath":"en/about/system-map.md","lastUpdated":1794216847000}'),r={name:"en/about/system-map.md"};function i(o,a,d,c,l,p){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="autonomous-driving-system-map" tabindex="-1">Autonomous-driving system map <a class="header-anchor" href="#autonomous-driving-system-map" aria-label="Permalink to &quot;Autonomous-driving system map&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sensors / chassis</span></span>
<span class="line"><span>    -&gt; drivers and message interfaces</span></span>
<span class="line"><span>    -&gt; time synchronization and coordinate transforms</span></span>
<span class="line"><span>    -&gt; localization / perception / prediction</span></span>
<span class="line"><span>    -&gt; planning</span></span>
<span class="line"><span>    -&gt; control</span></span>
<span class="line"><span>    -&gt; chassis actuation and feedback</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cross-cutting: configuration, visualization, log replay, simulation,</span></span>
<span class="line"><span>calibration, monitoring, and safety</span></span></code></pre></div><p>Start by finding the first layer where data deviates from expectations. Do not jump directly into planning or control parameters: timestamp, frame, extrinsic, and chassis-feedback errors upstream often appear as downstream algorithm instability.</p><h2 id="key-interface-checks" tabindex="-1">Key interface checks <a class="header-anchor" href="#key-interface-checks" aria-label="Permalink to &quot;Key interface checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry point</th><th>First verify</th></tr></thead><tbody><tr><td>Sensor</td><td>Driver publication, stable frequency, timestamp source</td></tr><tr><td>Message</td><td>Units, coordinate frame, <code>frame_id</code>, sequence continuity</td></tr><tr><td>Localization</td><td>Initialization, jumps, latency, covariance</td></tr><tr><td>Planning</td><td>Goal, constraints, map/no-map mode, trajectory timing</td></tr><tr><td>Control</td><td>Trajectory latency, vehicle-state feedback, actuator limits</td></tr><tr><td>Validation</td><td>Dataset, replay consistency, metrics, failure samples</td></tr></tbody></table><p>The map is diagnostic guidance, not evidence that every interface has been implemented or verified on a vehicle.</p><h2 id="industry-reference-architectures" tabindex="-1">Industry reference architectures <a class="header-anchor" href="#industry-reference-architectures" aria-label="Permalink to &quot;Industry reference architectures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Publicly visible structural practice</th><th>Implication for WheelOS</th></tr></thead><tbody><tr><td><a href="https://github.com/ApolloAuto/apollo" target="_blank" rel="noreferrer">Apollo</a></td><td>A modular driving stack is organized together with vehicle integration, calibration, data pipelines and simulation tools.</td><td>Product documentation should bind features to versions, configurations and integration prerequisites.</td></tr><tr><td><a href="https://docs.autoware.org/main/home/" target="_blank" rel="noreferrer">Autoware</a></td><td>Core packages, community extensions and tools are separated; installation, simulation, replay and component interfaces are documented.</td><td>Organize knowledge by task and interface; distinguish standard configuration from optional extensions.</td></tr><tr><td><a href="https://waymo.com/safety/" target="_blank" rel="noreferrer">Waymo</a></td><td>Public safety material emphasizes a safety case, operations and a combination of real-world and simulation validation.</td><td>A single demonstration cannot replace a safety case; disclose validation level, operating domain and residual risk.</td></tr></tbody></table><p>The shared direction is clear: modular interfaces, versioned configuration, layered validation, observability and explicit safety boundaries are all required. This comparison is design guidance; it is not evidence that WheelOS has reached the validation scale of these systems.</p><p>Public references: <a href="https://github.com/ApolloAuto/apollo" target="_blank" rel="noreferrer">Apollo repository</a> · <a href="https://docs.autoware.org/main/design/autoware-concepts/" target="_blank" rel="noreferrer">Autoware concepts</a> · <a href="https://docs.autoware.org/main/simulation/" target="_blank" rel="noreferrer">Autoware simulation</a> · <a href="https://waymo.com/safety/" target="_blank" rel="noreferrer">Waymo safety</a> · <a href="https://arxiv.org/abs/2306.01917" target="_blank" rel="noreferrer">Waymo safety case paper</a></p>`,10)])])}const u=t(r,[["render",i]]);export{h as __pageData,u as default};
